import "server-only";

import { neon } from "@neondatabase/serverless";

import { sendBookingChangeEmails } from "@/features/email/booking-change-email";
import { verifyCustomerCalendarToken } from "@/lib/customer-calendar";
import { resolveDatabaseUrl } from "@/lib/db/database-url";
import { parseLocalDateTime, resolveBookingTimeZone, validatePublicBookingPolicy } from "@/lib/public-booking-policy";

const connectionString = resolveDatabaseUrl();

export type RescheduleBookingData = {
  id: string;
  service: string;
  status: string;
  startsAt: string;
  endsAt: string;
  staffId: string | null;
  staffName: string | null;
  timeZone: string;
};

export async function getRescheduleBooking(token: string, bookingId: string): Promise<RescheduleBookingData | null> {
  const payload = verifyCustomerCalendarToken(token);
  if (!payload || !connectionString || !/^[0-9a-f-]{36}$/i.test(bookingId)) return null;
  const sql = neon(connectionString);
  const rows = await sql`
    select
      b.id,
      b.service,
      b.status,
      b.starts_at,
      b.ends_at,
      b.staff_id,
      s.name as staff_name,
      coalesce(nullif(ws.time_zone, ''), 'Europe/Stockholm') as time_zone
    from bookings b
    left join workspace_staff s on s.id = b.staff_id and s.workspace_id = b.workspace_id
    left join workspace_settings ws on ws.workspace_id = b.workspace_id
    left join workspace_booking_reminder_settings ps on ps.workspace_id = b.workspace_id
    where b.id = ${bookingId}
      and b.customer_id = ${payload.customerId}
      and b.workspace_id = ${payload.workspaceId}
      and coalesce(ps.customer_reschedule_enabled, true) = true
      and b.status in ('requested', 'confirmed')
      and b.starts_at > now()
      and b.source not in ('dashboard_availability_block', 'dashboard_availability_recurring_block')
    limit 1
  `;
  const row = rows[0];
  return row
    ? {
        id: String(row.id),
        service: String(row.service ?? "Bokning"),
        status: String(row.status),
        startsAt: new Date(String(row.starts_at)).toISOString(),
        endsAt: new Date(String(row.ends_at)).toISOString(),
        staffId: row.staff_id ? String(row.staff_id) : null,
        staffName: row.staff_name ? String(row.staff_name) : null,
        timeZone: String(row.time_zone),
      }
    : null;
}

export async function rescheduleCustomerBooking(token: string, bookingId: string, startsAtLocal: string) {
  const payload = verifyCustomerCalendarToken(token);
  if (!payload || !connectionString || !/^[0-9a-f-]{36}$/i.test(bookingId)) {
    return { ok: false as const, error: "invalid" };
  }

  const local = parseLocalDateTime(startsAtLocal);
  if (!local) return { ok: false as const, error: "time" };

  const sql = neon(connectionString);
  const rows = await sql`
    select
      b.id,
      b.service,
      b.city,
      b.staff_id,
      b.status as old_status,
      b.starts_at as old_starts_at,
      b.ends_at as old_ends_at,
      c.name as customer_name,
      c.email as customer_email,
      coalesce(nullif(ws.company_name, ''), w.company_name, w.name) as company_name,
      nullif(ws.contact_email, '') as owner_email,
      coalesce(nullif(ws.time_zone, ''), 'Europe/Stockholm') as time_zone,
      sv.duration_minutes,
      sv.buffer_before_minutes,
      sv.buffer_after_minutes,
      sv.minimum_notice_minutes,
      sv.maximum_advance_days,
      coalesce(ps.company_confirmation_required, true) as company_confirmation_required
    from bookings b
    join customers c on c.id = b.customer_id and c.workspace_id = b.workspace_id
    join workspaces w on w.id::text = b.workspace_id
    join workspace_services sv on sv.workspace_id = b.workspace_id and sv.name = b.service and sv.is_active = true
    left join workspace_settings ws on ws.workspace_id = b.workspace_id
    left join workspace_booking_reminder_settings ps on ps.workspace_id = b.workspace_id
    where b.id = ${bookingId}
      and b.customer_id = ${payload.customerId}
      and b.workspace_id = ${payload.workspaceId}
      and coalesce(ps.customer_reschedule_enabled, true) = true
      and b.status in ('requested', 'confirmed')
      and b.starts_at > now()
      and b.source not in ('dashboard_availability_block', 'dashboard_availability_recurring_block')
    limit 1
  `;
  const booking = rows[0];
  if (!booking) return { ok: false as const, error: "not_allowed" };

  const weekday = new Date(Date.UTC(local.year, local.month - 1, local.day)).getUTCDay();
  let hours: Record<string, unknown> | undefined;
  if (booking.staff_id) {
    hours = (await sql`
      select start_time::text as opens_at, end_time::text as closes_at, false as is_closed
      from workspace_staff_schedules
      where workspace_id = ${payload.workspaceId}
        and staff_id = ${String(booking.staff_id)}::uuid
        and weekday = ${weekday}
        and is_active = true
      limit 1
    `)[0];
  } else {
    hours = (await sql`
      select opens_at::text as opens_at, closes_at::text as closes_at, is_closed
      from workspace_booking_hours
      where workspace_id = ${payload.workspaceId}
        and weekday = ${weekday}
      limit 1
    `)[0];
  }

  const timeZone = resolveBookingTimeZone(booking.time_zone);
  const validation = validatePublicBookingPolicy({
    startsAt: startsAtLocal,
    now: new Date(),
    service: {
      durationMinutes: Math.max(1, Number(booking.duration_minutes) || 60),
      bufferBeforeMinutes: Math.max(0, Number(booking.buffer_before_minutes) || 0),
      bufferAfterMinutes: Math.max(0, Number(booking.buffer_after_minutes) || 0),
      minimumNoticeMinutes: Math.max(0, Number(booking.minimum_notice_minutes) || 0),
      maximumAdvanceDays: Math.max(1, Number(booking.maximum_advance_days) || 365),
    },
    bookingHour: hours
      ? {
          opensAt: String(hours.opens_at).slice(0, 5),
          closesAt: String(hours.closes_at).slice(0, 5),
          isClosed: Boolean(hours.is_closed),
        }
      : null,
    timeZone,
  });
  if (validation.error) return { ok: false as const, error: validation.error };

  const { start, end } = validation;
  if (
    booking.staff_id &&
    (await sql`
      select id
      from workspace_staff_time_off
      where workspace_id = ${payload.workspaceId}
        and staff_id = ${String(booking.staff_id)}::uuid
        and starts_at < ${end.toISOString()}::timestamptz
        and ends_at > ${start.toISOString()}::timestamptz
      limit 1
    `)[0]
  ) {
    return { ok: false as const, error: "time_off" };
  }

  const staffId = booking.staff_id ? String(booking.staff_id) : null;
  const conflict = await sql`
    select id
    from bookings
    where workspace_id = ${payload.workspaceId}
      and id <> ${bookingId}
      and status not in ('cancelled', 'no_show')
      and (${staffId}::uuid is null or staff_id = ${staffId}::uuid or staff_id is null)
      and starts_at < ${end.toISOString()}::timestamptz
      and ends_at > ${start.toISOString()}::timestamptz
    union all
    select id
    from public_booking_verifications
    where workspace_id = ${payload.workspaceId}::uuid
      and consumed_at is null
      and expires_at > now()
      and (${staffId}::uuid is null or staff_id = ${staffId}::uuid or staff_id is null)
      and starts_at < ${end.toISOString()}::timestamptz
      and ends_at > ${start.toISOString()}::timestamptz
    limit 1
  `;
  if (conflict[0]) return { ok: false as const, error: "conflict" };

  const nextStatus = Boolean(booking.company_confirmation_required) ? "requested" : "confirmed";
  const oldStart = new Date(String(booking.old_starts_at)).toISOString();
  const oldEnd = new Date(String(booking.old_ends_at)).toISOString();

  const updated = await sql`
    with updated_booking as (
      update bookings
      set starts_at = ${start.toISOString()}::timestamptz,
          ends_at = ${end.toISOString()}::timestamptz,
          status = ${nextStatus},
          updated_at = now()
      where id = ${bookingId}
        and customer_id = ${payload.customerId}
        and workspace_id = ${payload.workspaceId}
        and status in ('requested', 'confirmed')
        and starts_at > now()
      returning id, workspace_id, customer_id, status
    ),
    updated_job as (
      update workspace_service_jobs job
      set scheduled_starts_at = ${start.toISOString()}::timestamptz,
          scheduled_ends_at = ${end.toISOString()}::timestamptz,
          updated_at = now()
      from updated_booking
      where job.booking_id = updated_booking.id
        and job.workspace_id = ${payload.workspaceId}::uuid
        and job.status not in ('completed', 'cancelled')
      returning job.id, job.workspace_id
    ),
    job_event as (
      insert into workspace_service_job_events (
        workspace_id,
        service_job_id,
        event_type,
        summary,
        metadata
      )
      select
        workspace_id,
        id,
        'status_changed',
        'Service job schedule synchronized with a customer reschedule.',
        jsonb_build_object(
          'source', 'customer_portal_reschedule',
          'booking_id', ${bookingId},
          'previous_starts_at', ${oldStart},
          'previous_ends_at', ${oldEnd},
          'starts_at', ${start.toISOString()},
          'ends_at', ${end.toISOString()},
          'booking_status', ${nextStatus}
        )
      from updated_job
      returning id
    ),
    customer_event as (
      insert into customer_events (
        workspace_id,
        customer_id,
        booking_id,
        event_type,
        title,
        description,
        metadata
      )
      select
        workspace_id,
        customer_id,
        id,
        'booking',
        'Bokning ombokad av kund',
        'Kunden ändrade bokningstiden via Mina bokningar.',
        jsonb_build_object(
          'source', 'customer_portal',
          'event_subtype', 'booking_rescheduled',
          'previous_starts_at', ${oldStart},
          'previous_ends_at', ${oldEnd},
          'starts_at', ${start.toISOString()},
          'ends_at', ${end.toISOString()},
          'old_status', ${String(booking.old_status)},
          'new_status', ${nextStatus}
        )
      from updated_booking
      returning id
    )
    select id from updated_booking
  `;
  if (!updated[0]) return { ok: false as const, error: "not_allowed" };

  const base = (process.env.NEXT_PUBLIC_APP_URL ?? process.env.APP_URL ?? "https://www.proffera.se").replace(/\/$/, "");
  await sendBookingChangeEmails({
    kind: "rescheduled",
    customerName: String(booking.customer_name),
    customerEmail: String(booking.customer_email),
    ownerEmail: booking.owner_email ? String(booking.owner_email) : undefined,
    companyName: String(booking.company_name),
    service: String(booking.service ?? "Bokning"),
    city: String(booking.city ?? ""),
    oldStartsAt: oldStart,
    oldEndsAt: oldEnd,
    newStartsAt: start.toISOString(),
    newEndsAt: end.toISOString(),
    portalUrl: `${base}/mina-bokningar/${encodeURIComponent(token)}`,
    timeZone,
  });

  return { ok: true as const };
}
